#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7735.h>
#include <EEPROM.h>
#include "esp_arduino_version.h"

// ================= ПИНЫ (ESP32-C3 Super Mini, под вашу распайку) =================
// Дисплей ST7735S: BLC-5, CS-6, DC-2, RES-10, SDA-9, SCL-8
const int TFT_CS   = 6;   // CS дисплея
const int TFT_DC   = 2;   // DC (данные/команды)
const int TFT_RST  = 10;  // RESET дисплея
const int TFT_SCK  = 8;   // SPI-часы (SCL)
const int TFT_MOSI = 9;   // SPI-данные (SDA)
const int TFT_LED  = 5;   // подсветка (BLC)

// Остальное:
const int PWM_PIN  = 1;   // управление кулером (через транзистор!)
const int TACH_PIN = 4;   // тахо-провод кулера
const int NTC_PIN  = 0;   // термистор 10 кОм (АЦП есть только на GPIO0-4!)
const int BTN_MODE = 3;   // выбор параметра
const int BTN_UP   = 7;   // увеличить
const int BTN_DOWN = 20;  // уменьшить
// GPIO21 остался свободным

Adafruit_ST7735 tft(TFT_CS, TFT_DC, TFT_RST);

// ================= ТЕРМИСТОР =================
// Схема: 3.3V -- 10k -- точка замера(GPIO0) -- NTC -- GND
const float R_SERIES  = 10000.0;
const float R_NOMINAL = 10000.0;
const float B_COEFF   = 3950.0;
const float T_NOMINAL = 25.0;
const float ADC_MAX   = 4095.0;

// ================= КУЛЕР =================
const float PULSES_PER_REV = 2.0;

// ================= НАСТРОЙКИ =================
float tOn  = 30.0;
float tOff = 25.0;
byte  fanSpeed = 60;

const int ADDR_EE = 0;

// ================= ПЕРЕМЕННЫЕ =================
volatile unsigned long tachCount = 0;
unsigned long lastRpmMs = 0;
unsigned int rpm = 0;
bool fanOn = false;
bool tachPresent = false;

byte menu = 0;
unsigned long menuTimeout = 0;

void IRAM_ATTR tachISR() {
  tachCount++;
}

float readTemp() {
  long sum = 0;
  for (byte i = 0; i < 20; i++) sum += analogRead(NTC_PIN);
  float adc = sum / 20.0;
  if (adc < 1 || adc > 4094) return -999;

  float rNtc = R_SERIES * adc / (ADC_MAX - adc);
  float tK = 1.0 / (1.0 / (T_NOMINAL + 273.15)
             + log(rNtc / R_NOMINAL) / B_COEFF);
  return tK - 273.15;
}

void loadSettings() {
  EEPROM.get(ADDR_EE, tOn);
  EEPROM.get(ADDR_EE + sizeof(float), tOff);
  EEPROM.get(ADDR_EE + 2 * sizeof(float), fanSpeed);
  if (isnan(tOn) || tOn > 100 || tOn < -20) tOn = 30.0;
  if (isnan(tOff) || tOff > 100 || tOff < -20) tOff = 25.0;
  if (fanSpeed > 100) fanSpeed = 60;
}

void saveSettings() {
  EEPROM.put(ADDR_EE, tOn);
  EEPROM.put(ADDR_EE + sizeof(float), tOff);
  EEPROM.put(ADDR_EE + 2 * sizeof(float), fanSpeed);
  EEPROM.commit();
}

bool pressed(int pin) {
  if (digitalRead(pin) == LOW) {
    delay(25);
    if (digitalRead(pin) == LOW) {
      while (digitalRead(pin) == LOW) delay(10);
      return true;
    }
  }
  return false;
}

void setup() {
  pinMode(TFT_LED, OUTPUT);
  digitalWrite(TFT_LED, HIGH);

  pinMode(TACH_PIN, INPUT_PULLUP);
  pinMode(BTN_MODE, INPUT_PULLUP);
  pinMode(BTN_UP,   INPUT_PULLUP);
  pinMode(BTN_DOWN, INPUT_PULLUP);
  pinMode(PWM_PIN, OUTPUT);

  analogWriteFrequency(PWM_PIN, 25000);
  analogWriteResolution(8);
  analogWrite(PWM_PIN, 0);

  EEPROM.begin(32);
  loadSettings();

  SPI.begin(TFT_SCK, -1, TFT_MOSI, TFT_CS);
  tft.initR(INITR_BLACKTAB);
  tft.setRotation(0);
  tft.fillScreen(ST77XX_BLACK);
  tft.setTextColor(ST77XX_WHITE, ST77XX_BLACK);
  tft.setTextWrap(false);

  tft.setTextSize(1);
  tft.setCursor(0, 0);
  tft.print("Termo fan controller");
  tft.setTextSize(2);
  tft.setCursor(0, 16);
  tft.print("ST7735 ready");
  delay(1000);

  attachInterrupt(TACH_PIN, tachISR, FALLING);
  lastRpmMs = millis();
}

void loop() {
  float temp = readTemp();

  if (temp > -100) {
    if (!fanOn && temp >= tOn) fanOn = true;
    if (fanOn  && temp <= tOff) fanOn = false;
  } else {
    fanOn = false;
  }
  analogWrite(PWM_PIN, fanOn ? map(fanSpeed, 0, 100, 0, 255) : 0);

  if (millis() - lastRpmMs >= 1000) {
    noInterrupts();
    unsigned long cnt = tachCount;
    tachCount = 0;
    interrupts();
    if (cnt > 0) { tachPresent = true; }
    if (fanOn && tachPresent && cnt > 0) {
      rpm = cnt * 60.0 / PULSES_PER_REV;
    } else {
      rpm = 0;
    }
    lastRpmMs = millis();
  }

  if (pressed(BTN_MODE)) {
    menu = (menu + 1) % 4;
    if (menu == 0) saveSettings();
    menuTimeout = millis();
  }
  if (menu > 0) {
    int delta = 0;
    if (pressed(BTN_UP))   delta = +1;
    if (pressed(BTN_DOWN)) delta = -1;
    if (delta) {
      menuTimeout = millis();
      if (menu == 1) { tOn  += delta * 0.5; if (tOn  < -20) tOn = -20; if (tOn  > 100) tOn = 100; }
      if (menu == 2) { tOff += delta * 0.5; if (tOff < -20) tOff = -20; if (tOff > 100) tOff = 100; }
      if (menu == 3) { fanSpeed += delta * 5; if (fanSpeed < 0) fanSpeed = 0; if (fanSpeed > 100) fanSpeed = 100; }
      if (tOff > tOn - 1.0) {
        if (menu == 1) tOn = tOff + 1.0;
        else tOff = tOn - 1.0;
      }
    }
    if (millis() - menuTimeout > 5000) { menu = 0; saveSettings(); }
  }

  tft.setTextSize(2);
  tft.setCursor(0, 4);
  if (temp > -100) {
    tft.setTextColor(fanOn ? ST77XX_GREEN : ST77XX_WHITE, ST77XX_BLACK);
    tft.print("T: "); tft.print(temp, 1); tft.print(" C  ");
  } else {
    tft.setTextColor(ST77XX_RED, ST77XX_BLACK);
    tft.print("T: ERR!   ");
  }

  tft.setTextColor(ST77XX_WHITE, ST77XX_BLACK);
  tft.setCursor(0, 28);
  tft.print("Fan: ");
  tft.setTextColor(fanOn ? ST77XX_GREEN : ST77XX_RED, ST77XX_BLACK);
  tft.print(fanOn ? "ON " : "OFF");
  tft.setTextColor(ST77XX_WHITE, ST77XX_BLACK);
  tft.print(" "); tft.print(fanSpeed); tft.print("%  ");

  tft.setCursor(0, 50);
  tft.print("RPM: ");
  tft.print(rpm); tft.print("     ");

  tft.setTextSize(2);
  tft.setCursor(0, 78);
  tft.setTextColor(menu == 1 ? ST77XX_YELLOW : ST77XX_WHITE, ST77XX_BLACK);
  tft.print(menu == 1 ? ">" : " ");
  tft.print(" T on:  "); tft.print(tOn, 1); tft.print("   ");

  tft.setCursor(0, 100);
  tft.setTextColor(menu == 2 ? ST77XX_YELLOW : ST77XX_WHITE, ST77XX_BLACK);
  tft.print(menu == 2 ? ">" : " ");
  tft.print(" T off: "); tft.print(tOff, 1); tft.print("   ");

  tft.setCursor(0, 122);
  tft.setTextColor(menu == 3 ? ST77XX_YELLOW : ST77XX_WHITE, ST77XX_BLACK);
  tft.print(menu == 3 ? ">" : " ");
  tft.print(" Spd:   "); tft.print(fanSpeed); tft.print("%  ");

  delay(150);
}
